<script>export let data;let animal='all';let category='all';$: guides=data.guides.filter(g=>(animal==='all'||g.animal_type===animal)&&(category==='all'||g.category===category));</script><section class="page"><div class="eyebrow">ANIMAL CARE</div><h1>Small guides. Better care.</h1><p class="sub">Curated general information for cats and dogs. For medical concerns, contact a veterinarian.</p><div class="toolbar"><select bind:value={animal}><option value="all">All animals</option><option value="Dog">Dogs</option><option value="Cat">Cats</option></select><select bind:value={category}><option value="all">All topics</option><option value="Care">Care</option><option value="Food">Food</option><option value="Do & Don’t">Do & Don't</option></select></div><div class="guide-grid">{#each guides as g}<article class="guide"><span class="tag">{g.animal_type} · {g.category}</span><h3>{g.title}</h3><p>{g.content}</p></article>{/each}</div></section>
